// MARK: - Errors

/// Error enum for DSQL
public struct DSQLErrorType: AWSErrorType, Decodable {
    @nonexhaustive
    public enum Code: Sendable {
        /// You do not have sufficient access to perform this action.
        case accessDeniedException
        /// The submitted action has conflicts.
        case conflictException(DSQL.ConflictException)
        /// The request processing has failed because of an unknown error, exception or failure.
        case internalServerException(DSQL.InternalServerException)
        /// The resource could not be found.
        case resourceNotFoundException(DSQL.ResourceNotFoundException)
        /// The service limit was exceeded.
        case serviceQuotaExceededException(DSQL.ServiceQuotaExceededException)
        /// The request was denied due to request throttling.
        case throttlingException(DSQL.ThrottlingException)
        /// The input failed to satisfy the constraints specified by an Amazon Web Services service.
        case validationException(DSQL.ValidationException)
    }

    public let error: Code
    public let message: String?
    public let response: HTTPResponse?

    public init(from decoder: any Decoder) throws {
        let singleValueContainer = try decoder.singleValueContainer()
        let responseError = try singleValueContainer.decode(AWSResponseError.self)
        switch responseError.errorCode {
        case "AccessDeniedException": self.error = .accessDeniedException
        case "ConflictException":
            let context = try singleValueContainer.decode(DSQL.ConflictException.self)
            self.error = .conflictException(context)
        case "InternalServerException":
            let context = try singleValueContainer.decode(DSQL.InternalServerException.self)
            self.error = .internalServerException(context)
        case "ResourceNotFoundException":
            let context = try singleValueContainer.decode(DSQL.ResourceNotFoundException.self)
            self.error = .resourceNotFoundException(context)
        case "ServiceQuotaExceededException":
            let context = try singleValueContainer.decode(DSQL.ServiceQuotaExceededException.self)
            self.error = .serviceQuotaExceededException(context)
        case "ThrottlingException":
            let context = try singleValueContainer.decode(DSQL.ThrottlingException.self)
            self.error = .throttlingException(context)
        case "ValidationException":
            let context = try singleValueContainer.decode(DSQL.ValidationException.self)
            self.error = .validationException(context)
        default:
            throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "Unrecognised error code"))
        }
        self.message = responseError.message
        self.response = responseError.response
    }

    /// return error code string
    public var errorCode: String {
        switch error {
        case .accessDeniedException: "AccessDeniedException"
        case .conflictException: "ConflictException"
        case .internalServerException: "InternalServerException"
        case .resourceNotFoundException: "ResourceNotFoundException"
        case .serviceQuotaExceededException: "ServiceQuotaExceededException"
        case .throttlingException: "ThrottlingException"
        case .validationException: "ValidationException"
        }
    }
}
